    operator bool() const { return p != nullptr; }
    operator uint64_t() const { return reinterpret_cast<uint64_t>(p); }
    uint8_t &operator[](size_t i) const { return reinterpret_cast<uint8_t *>(p)[i]; }
    uint8_t &operator*() const { return *reinterpret_cast<uint8_t *>(p); }
    mset_ptr operator+(ptrdiff_t n) const { return mset_ptr{static_cast<uint8_t *>(p) + n}; }
