// Ghidra "code": callable of unknown signature.  Accepts any function pointer
// on assignment and returns mset_ptr so call results can flow into typed
// pointers the way the decompiler expects.
struct mset_code {
    void *fn;
    mset_code() : fn(nullptr) {}
    mset_code(void *p) : fn(p) {}          // raw-address / cast path
    mset_code(uintptr_t v) : fn(reinterpret_cast<void *>(v)) {}
    template <class R, class... A>
    mset_code(R (*f)(A...)) : fn(reinterpret_cast<void *>(f)) {}
    mset_code &operator*() { return *this; }
    const mset_code &operator*() const { return *this; }
    template <class... A>
    mset_ptr operator()(A... args) const {
        using F = mset_ptr (*)(...);
        return reinterpret_cast<F>(fn)(args...);
    }
    bool operator==(int) const { return fn == nullptr; }
    bool operator!=(int) const { return fn != nullptr; }
};
