// Complex arithmetic used by the Mandelbrot inner loops.
inline complex_double operator+(complex_double a, complex_double b) { return {a.re + b.re, a.im + b.im}; }
inline complex_double operator-(complex_double a, complex_double b) { return {a.re - b.re, a.im - b.im}; }
inline complex_double operator*(complex_double a, complex_double b) {
    return {a.re * b.re - a.im * b.im, a.re * b.im + a.im * b.re};
}
inline complex_double operator/(complex_double a, complex_double b) {
    const double d = b.re * b.re + b.im * b.im;
    return {(a.re * b.re + a.im * b.im) / d, (a.im * b.re - a.re * b.im) / d};
}
inline complex_double &operator+=(complex_double &a, complex_double b) { a = a + b; return a; }
inline complex_double &operator-=(complex_double &a, complex_double b) { a = a - b; return a; }
