inline uint64_t mset_concat(uint64_t hi, uint64_t lo, unsigned lo_bytes,
                            unsigned total_bytes = 8u) {
    const unsigned shift = lo_bytes * 8u;
    if (shift >= 64u) {
        return lo;      // 80-bit CONCAT28: high 16 bits do not fit a uint64_t
    }
    const uint64_t mask = (1ull << shift) - 1ull;
    uint64_t v = (hi << shift) | (lo & mask);
    if (total_bytes < 8u) {
        v &= (1ull << (total_bytes * 8u)) - 1ull;
    }
    return v;
}
inline uint64_t mset_sub(uint64_t value, unsigned offset, unsigned width) {
    const unsigned shift = offset * 8u;
    uint64_t mask = (width >= 8u) ? ~0ull : ((1ull << (width * 8u)) - 1ull);
    return (value >> shift) & mask;
}

// Address-level data symbol.  Ghidra references some globals both as raw
// addresses and as typed scalars; this shim keeps both spellings valid so the
// recovered translation unit compiles without inventing storage.
struct mset_global {
    union {
        uint8_t _bytes[4096];
        struct { uint32_t _0_4_, _4_4_; };
        struct { uint64_t _0_8_, _8_8_; };
    };
    operator uint8_t *() { return _bytes; }
    operator const uint8_t *() const { return _bytes; }
    template <class T> operator T *() { return reinterpret_cast<T *>(_bytes); }
    operator double() const { double v; std::memcpy(&v, _bytes, sizeof v); return v; }
    operator uint64_t() const { uint64_t v; std::memcpy(&v, _bytes, sizeof v); return v; }
    uint8_t &operator[](size_t i) { return _bytes[i]; }
    const uint8_t &operator[](size_t i) const { return _bytes[i]; }

    // Scalar stores back into a data symbol (Ghidra writes through the address).
    mset_global &operator=(uint64_t v) { std::memcpy(_bytes, &v, 8); return *this; }
    mset_global &operator=(uint32_t v) { std::memcpy(_bytes, &v, 4); return *this; }
    mset_global &operator=(int32_t v)  { std::memcpy(_bytes, &v, 4); return *this; }
    mset_global &operator=(double v)   { std::memcpy(_bytes, &v, 8); return *this; }
    mset_global &operator=(void *p)    { std::memcpy(_bytes, &p, sizeof p); return *this; }
};

inline mset_ptr mset_malloc(size_t n) { return mset_ptr{std::malloc(n)}; }
inline mset_ptr mset_calloc(size_t n, size_t s) { return mset_ptr{std::calloc(n, s)}; }
inline mset_ptr mset_realloc(void *p, size_t n) { return mset_ptr{std::realloc(p, n)}; }
#define malloc(n)      mset_malloc(n)
#define calloc(n, s)   mset_calloc((n), (s))
#define realloc(p, n)  mset_realloc((p), (n))

